def F(name,product,where,what,tier,sources,shots,conf):
    return dict(name=name,product=product,where=where,what=what,plan_tier=tier,sources=sources,screenshots=shots,confidence=conf)
G="Clio Grow"; S="Clio Scheduler"; M="Clio Manage"; AI="Grow AI (Clio Grow add-on)"
GT="Clio Grow licence (sold with top Clio suite tier or as add-on; exact tier naming unconfirmed)"
features=[
F("Lead inbox: marketing vs appointment leads",G,"Leads > Marketing (Untriaged / Ignored) and Leads > Appointments","Leads are split by origin: marketing channels (integrations, lead-capture API, Clio website, Google LSA) and Clio Scheduler bookings. Each has its own triage actions.",GT,[LEADS],[GROWPG],"high"),
F("Accept lead as contact only, or Quick Intake (contact + matter), optionally with conflict check",G,"Leads > Marketing > Untriaged > Accept > Add contact | Quick Intake","Accepting a marketing lead either creates just a contact or a contact plus intake matter. Quick Intake can launch a conflict check from the same form.",GT,[LEADS],[],"high"),
F("Ignore, mark as spam, restore, delete all ignored",G,"Leads > Marketing > Untriaged > Remove; Ignored subtab","Unwanted leads go to an Ignored state and can be restored to Untriaged or bulk-deleted. Spam marking is separate.",GT,[LEADS],[],"high"),
F("Appointment lead accept / ignore-and-cancel",G,"Leads > Appointments > Accept | Ignore lead and cancel appointment","A Scheduler booking is accepted by linking or creating a contact and matter (then Create matter or Save and run conflict check), or the lead is deleted and the appointment cancelled.",GT,[LEADS],[],"high"),
F("Lead capture token and Lead Inbox API endpoint",G,"Settings > Integrations > Lead capture","Per-firm token lets third-party sources or a firm's own web form post leads into the inbox via an API endpoint.",GT,[LEADS],[],"high"),
F("New-lead email notification",G,"Settings > Personal > Notification settings","Per-user checkbox to get an email when a lead reaches the inbox.",GT,[LEADS],[],"high"),
F("Grow AI fit assessment with human override",AI,"Lead detail > Review assessment; rating dropdown","AI summarises each lead and labels fit (mobile shows Good / Possible / Poor fit) using practice area, served location and conflict likelihood. Staff can change the label and view reasons.","Grow AI, billed per hired matter",[LEADS,MOB],[],"high"),
F("Take over screening from AI (permanent per lead)",AI,"Clio mobile > Leads > lead > Take over screening from AI","A user can stop AI screening for one lead; AI never resumes on that lead.","Grow AI",[MOB],[],"high"),
F("Grow AI website chat",AI,"Settings > Grow AI > Go live > Web chat","24/7 chat widget (snippet, WordPress plugin, or Clio-built site) that collects contact and case facts, answers FAQs and offers booking to qualifying leads. Transcript is viewable on the lead. Toggles cover AI disclosure and a privacy-policy link.","Grow AI; phased release",[CHAT,LEADS],[PRESS],"high"),
F("Grow AI voice agent",AI,"Settings > Grow AI > Go live > Phone","After-hours or busy-line calls are forwarded to a Clio-assigned number. The agent screens the caller, books a consult on the call, and leaves a summary, full transcript, lead score and the reason intake did not finish (if it did not). Voice, greeting and AI disclosure are configurable.","Grow AI; US only",[VOICE],[],"high"),
F("Grow AI email agent",AI,"Settings > Grow AI > Go live > Email > Connect inbox","Watches a connected inbox, replies to direct prospect emails to gather details, screens and books. Referrals, third-party lead notifications and unclear senders are routed as 'For review' with no reply. Connecting also turns on automated email filing. Settings cover the sign-off and AI disclosure.","Grow AI",[EMAILAG],[],"high"),
F("Grow AI intake criteria per practice area",AI,"Settings > Grow AI > Intake criteria","Per practice area: fields to collect (name, email, phone, situation summary and matter location always collected; practice-specific extras such as date of separation), up to 10 served locations, and an appointment booking toggle with an appointment type and post-booking action.","Grow AI",[CUST],[],"high"),
F("Grow AI FAQ, languages, import-from-website, test panel",AI,"Settings > Grow AI > FAQ | Languages | Import from website; right-side test panel","Firm-edited FAQ answers, a primary language plus extra languages, criteria suggested by reading the firm website, and a sandbox to test email, chat and phone before going live.","Grow AI",[CUST],[],"high"),
F("Grow AI automated follow-ups",AI,"Grow AI (lead and document flows)","Chases leads with an incomplete form, unsigned agreement or unbooked consult. Document prep offers AI follow-ups for signatures.","Grow AI",[GAI,DOCS],[],"high"),
F("Grow AI outcome-based billing, hiring target, cost controls, activity log",AI,"Settings > Subscription > Billing | Activity","Charged per matter set to Hired that AI assisted. Includes a free trial of hires, a monthly hiring target that pauses AI when met (not a hard billing cap), usage alerts, threshold invoicing, and an activity history of every AI action.","Grow AI",[SUB,GAI],[],"high"),
F("Firm-wide AI off switch",G,"Settings > Account > Open AI settings","An admin can turn Grow AI off for all users without affecting Clio Manage AI.","All Grow",[GAI],[],"high"),
F("Intake form templates with question types and follow-ups",G,"Forms > Templates > New template","Question types: single-line, paragraph, multiple choice, multi-select, dropdown, file (50MB max), date, yes/no, plus section breaks. Follow-up questions can hang off yes/no and multiple-choice answers. Questions can be required, carry descriptions, and map to custom fields. A form can hold several contact blocks.",GT,[QF,FORMS],[FORMPG],"high"),
F("Form languages",G,"Forms > Templates > Form language","English by default; Spanish, French, Portuguese or German. Only Clio-provided labels are translated, not the firm's own questions.",GT,[FORMS],[],"high"),
F("Public form settings",G,"Forms > Templates > Public Form Settings","A public link or embed. On submit it sets the pipeline status, matter type, assignee and confirmation sender, and auto-creates a contact and matter. Forms cannot be archived, only deleted.",GT,[FORMS],[],"high"),
F("Send form, Quick Form, due dates, reminders, link expiry",G,"Matter > Intake process > Prepare Form; Forms > Pending; Quick Intake > Quick Form","Forms go by email with an SMS toggle. Quick Form creates a contact, matter and form in one step and can be filled in live during a call. Due dates and reminders apply. Links last 14 days and can be refreshed by the client until day 30, after which the firm must resend.",GT,[SEND],[],"high"),
F("Communication templates, connected mailbox, email sequences, checklist templates",G,"Settings > Communication templates; Settings > Checklists and sequences; Settings > Communications","Email templates for forms, documents, appointments and payment requests (only one reminder template each for forms and documents). Firms can connect Gmail, Outlook, Exchange or SMTP, with optional auto-filing. Checklist templates bundle tasks, forms, documents and emails; email sequences bundle emails, applied in a matter's Intake process.",GT,[SEQ,TASKS],[],"high"),
F("Automated workflows (templates: Rapid intake, Screening inbox leads, Comprehensive intake)",G,"Settings > Automated workflows","Step types: request form, change matter status, schedule appointment (sends booking link), send email, and assign task (blocks later steps until done; suggested for conflict checks). Draft workflows are editable. A published workflow must be cancelled and recreated to change it. Workflows apply per matter and show Running, Completed or error states. Only admins build them.",GT,[WF],[GROWPG],"high"),
F("Pipeline board with Intake / Hired / Not hired categories",G,"Pipeline","Columns are firm-defined matter statuses grouped into three categories. Cards can be dragged, quick-hired or not-hired (check/x), and opened in Quick view. Filters: assignee, matter type, first-touch marketing source, value, created date, and 'needs the firm's attention' (workflow error or New). A setting can default the board to my matters only.",GT,[PIPE],[GROWPG],"high"),
F("Grow dashboard",G,"Dashboard","Shows pipeline health (to review, ignored, lead acceptance rate), performance (leads, estimated value), and a Local Services Ads view.",GT,[DASH],[],"high"),
F("Reports: matter revenue, lead source revenue, matters added, referral",G,"Reports","The matter revenue report joins Grow source and status data with Manage billed, unbilled and collected figures. The lead source report shows intake, hired, not hired, conversion, estimated value and revenue, plus spend and ROI for Google LSA. The matters-added report charts volume, pipeline value and conversion. The referral report gives totals and values per referrer. All export to CSV.",GT,[REP],[],"high"),
F("Marketing sources and campaigns (attribution)",G,"Settings > Marketing > Sources / Campaigns; matter Marketing panel","Standard sources plus named campaigns. A matter can carry several sources, a contact only one. LSA sources are auto-applied and locked.",GT,[SRC],[],"high"),
F("Email marketing campaigns",G,"Marketing > Create campaign","Starts from an objective template or a custom campaign. Recipients are filtered by tag, contact type, matter type, status, pending form or document, practice area and close date (newest 5,000 max). Bounced, unsubscribed and Did-not-hire contacts are auto-removed. Includes an AI email draft, test send, an automatic firm name/address footer with unsubscribe, sending in batches, and open, click and revenue metrics. Automated campaigns such as birthdays need Grow AI. A sent campaign cannot be undone.",GT,[MKT],[MKTPG],"high"),
F("Reputation management (review requests)",G,"Reputation (left nav)","Review requests go by email or SMS, manually or automatically at matter close per practice area, with reminders. A dashboard shows requests, click-through and status (clicked, reminder sent, failed).","Clio Grow; phased",[REPU],[REPPG],"high"),
F("Google Local Services Ads integration",G,"Settings > Marketing > Marketing channels","Firms apply for LSA inside Grow, and LSA leads arrive in the inbox where they can be disputed. Spend and ROI appear in reports. US only, for listed practice areas.","Clio Grow, US",[LSA,DASH],[],"high"),
F("Clio Grow website builder",G,"Settings > Logo & letterhead / Website","No-code firm website with custom domain mapping. Clients can book and pay from it, and Grow AI chat can be toggled on. Content is lost if the firm leaves Clio.",GT,[WEB,CHAT],[],"high"),
F("SMS notifications and reminders (no-reply from Grow)",G,"Settings > Communications > Enable text message notifications","Uses the firm's verified toll-free number from Manage, for +1 numbers only. Templates are fixed and cannot be edited. Texts from Grow are no-reply; two-way texting happens in Manage. Manual texts appear on the timeline but automated reminders do not. Failure reasons are listed.",GT+"; requires Manage texting",[SMS],[],"high"),
F("Appointment reminders",G,"Settings > Appointments > Automated reminders; appointment > Add a reminder","Up to 5 automated email/SMS reminders per appointment, with firm-wide defaults that also apply to Scheduler bookings, plus manual email reminders.",GT,[REM],[],"high"),
F("Clio Scheduler appointment types and firm booking page",S,"Clio Grow > Settings > Appointments > Clio Scheduler appointments","Each type has a description, location, internal note, Zoom option, duration, weekly availability, start increments, minimum notice and buffers before and after (not shown in Manage), plus invitation, confirmation and reminder templates. Each type has its own link, and a firm booking page lists several types. Settings cover display name and logo. Pausing means unchecking all days or blocking with a Manage calendar event. Unpaid bookings land in the lead inbox and paid bookings go to the pipeline.","Requires Clio Grow",[SCHED,WBK],[APPTPG],"high"),
F("Paid consultations at booking",S,"Appointment type > Collect payments","Clio Payments (North America) takes card, Apple Pay or Google Pay. The firm sets the status for paid leads, the amount and the deposit account, and records it as earned or as a credit on the contact. With a trust account, only a credit for future billing is allowed.","Grow + Manage + Clio Payments",[WBK,SCHED],[],"high"),
F("Request payment from a lead before conversion",G,"Matter > Intake process > Schedule or send > Request payment","Generates a payment link, logged as a checklist item with status. Manual payments can be recorded and synced to Manage.","Grow + Manage + Clio Payments",[PAY],[],"high"),
F("Intake documents and e-signature",G,"Matter > Intake process > Prepare document; Documents > Pending","Documents are auto-filled from templates or uploaded as a one-off PDF or Word file with placed fields. They are signed via Dropbox Sign, with due dates, reminders, resend and multiple signers.",GT,[DOCS],[],"high"),
F("Tasks, checklists and Agenda",G,"Matter > Intake process; Agenda","Intake tasks with multiple assignees and reminders. Grow tasks do not sync to Manage tasks, but they can show on the Manage calendar.",GT,[TASKS],[],"high"),
F("Mobile lead triage",G+" in Clio mobile app","Clio mobile > Home > Leads","Inbox with Priority leads (appointments today or tomorrow, then good-fit leads), filters, assessment, accept/remove, and call or email actions. There is no search.","Manage + Grow licence",[MOB],[],"high"),
F("Conflict check runs (shared Grow/Manage)",M+" / "+G,"Global search > Run conflict check; Contacts > Conflict checks; Matter > Conflicts check; Save and run conflict check; Grow lead intake","Up to 10 searches per check. Each search is a Person, Company or Keyword subject with name variations, a 'match full name' toggle, a label, extra identifiers (email, phone, address, DOB) and Flex or Exact matching, and searches Grow, Manage or both. Results get a status and note per hit, with bulk statuses and status subtabs. Any user can share a link to the results.","Select plans; admins and General Access users run checks",[CC],[],"high"),
F("Close check and report; 3-day auto-close; duplicate and re-run",M+" / "+G,"Conflict check > Close and generate report","The overall status comes from the per-hit statuses. Overriding it needs a disclaimer acknowledgement. Closing produces a PDF report with comments, a share link, the parameters and a matter association. Checks auto-close after 3 days. A closed check can be duplicated and re-run, and the list exports to CSV.","Select plans",[CC],[],"high"),
F("Firm-wide conflict search preferences and categories",M,"Conflict check summary > Conflict check preferences","Default subject type, Flex or Exact, and categories (calendar events, notes, document names, communication logs). On Advanced or higher, document and event-description contents are searched too.","Essentials, Advanced, Expand",[CCS],[],"high"),
F("Know Your Client / Know Your Business field set",M,"Settings > Firm Preferences > Compliance > KYC/KYB is enabled","Records dates of the conflict, ID, AML and source-of-funds checks plus a risk rating and reason, on contacts and on matters (risk at opening and closing). It is a log, not a verification workflow, and is region-gated.","Select plans; region-dependent",[KYC],[],"high"),
F("Grow AI conflict flag on leads",AI,"Lead assessment","AI flags possible conflicts during lead screening. Mobile shows the share of matching records already in Clio and the conflict-check result.","Grow AI",[GAI,MOB],[],"high"),
]
gaps=[
dict(feature="Email marketing campaigns (segments, AI draft, unsubscribe, metrics, revenue attribution)",our_area="intake",our_screen=None,status="missing",proposal="Add screen 'marketing-campaigns' (/intake/campaigns). Fields: name, objective, segment filters (contact type, practice area, stage, tag, closed-between, pending questionnaire), consent_basis per recipient (CASL express or implied with an expiry date), subject, body, sender, footer with firm address and a one-click unsubscribe. Actions: Draft copy (agent), Preview the excluded list (no consent, implied consent expired, unsubscribed, bounced, opposing parties or pre-conflict hits), Test send, and Send under a new gate G-mkt where a lawyer approves the content and the segment, logged. Metrics are opens, clicks, and matters and revenue per campaign. Rules: block any recipient without a valid CASL basis, and never send to a declined or sealed prospect.",priority="should"),
dict(feature="Review requests / reputation dashboard",our_area="intake",our_screen=None,status="missing",proposal="Add a 'review-requests' setting and job: when a matter closes, offer a review request (per practice area, off by default) by email or SMS with one reminder. Dashboard shows sent, clicked and failed. Rules: a lawyer approves the template (G-form). No incentives and no sentiment gating (ask everyone or no one). Exclude matters with an open complaint, a fee dispute or a confidentiality flag. Check LSO marketing rules (Rule 4.2) on testimonials.",priority="could"),
dict(feature="Marketing source + campaign attribution, multi-touch on matters",our_area="intake",our_screen="intake-settings",status="partial",proposal="Add campaigns[] to intake-settings and Lead.campaign_id. Allow several sources on a matter (first_touch and later touches), keeping one source per contact. referral-sources-report gets group_by=campaign and an optional spend field per source or campaign (manual entry or CSV) to compute ROI.",priority="should"),
dict(feature="AI email intake agent with 'For review' routing",our_area="intake",our_screen="lead-inbox",status="partial",proposal="Mailbox watcher exists. Add an explicit triage outcome 'for_review' to Lead (for referrals from lawyers, third-party lead notifications and unclear senders), with no auto-reply. Add a configurable reply sign-off (must say 'intake assistant, not a lawyer') and an always-on AI disclosure. The agent may reply only to collect facts and offer booking. Anything substantive goes to the existing approval path.",priority="must"),
dict(feature="AI receptionist configuration: per-practice-area info to collect, served locations, FAQ, languages, import from website, test console",our_area="intake",our_screen="ai-receptionist",status="partial",proposal="Add to ai-receptionist: practice_area_profiles[] (required_fields, optional_fields, service_area, booking_enabled, consult_type), a faq[] editor (each answer passes G-form), languages (primary en, optional fr), 'Suggest criteria from firm website' (agent drafts, lawyer approves), and a Test console tab (chat, email, phone) that runs the live config against the sandbox and never creates real leads.",priority="should"),
dict(feature="Fit label override and 'take over from agent' per lead",our_area="intake",our_screen="lead-detail",status="partial",proposal="Add Lead.fit enum good|possible|poor|tbd plus fit_reasons[] and fit_overridden_by. Add action 'Take over from agent' (by human, no gate) that stops all agent screening and sequences for that lead permanently, with an audit event. Mobile-width layout for the lead-inbox triage list (Priority = consults today or tomorrow, then good fit).",priority="should"),
dict(feature="AI cost controls: outcome target, usage alerts, activity log",our_area="intake",our_screen="intake-dashboard",status="partial",proposal="We do not charge per hire, but firms still need control. Add an 'Agent activity' panel listing every intake action the agent took (message sent, booked, chased) with filters, plus a monthly cap on agent-handled conversations or messages that pauses new outreach when reached (finishing in-flight work), and an alert at 80%.",priority="could"),
dict(feature="Request payment / retainer from a lead before conversion",our_area="intake",our_screen="lead-detail",status="partial",proposal="Add action 'Request retainer or consult payment' that generates a payment link through the billing/trust payment provider. Money for future services is always deposited to trust and recorded as client money (Ontario By-Law 9), never as earned. The status shows on the lead timeline. A refund needs G-fee. Mirror Clio's rule that trust deposits can only be a credit, never 'fees earned'.",priority="should"),
dict(feature="Quick Form (create contact+matter+form in one, fill live on the phone)",our_area="intake",our_screen="phone-and-email-capture",status="partial",proposal="Add action 'Fill questionnaire now' on phone-and-email-capture. It opens the selected intake form in staff-fill mode, prefilled from the extracted fields, and saves as an IntakeSubmission with taken_by.",priority="could"),
dict(feature="Pipeline 'needs attention' filter and quick hire/not-hire",our_area="intake",our_screen="crm-pipeline",status="partial",proposal="Add filter 'needs attention' (new and untouched, sequence error, SLA breach, stalled > N days), filters for first-touch source and value band, 'my leads only' as the default per user, and card quick actions Hire (opens G1 accept) and Not hired (lost_reason required).",priority="should"),
dict(feature="Automation step: blocking human task (e.g. run conflict check) and visible step state",our_area="intake",our_screen="intake-automations",status="partial",proposal="Add step type 'human task' (assignee, due, reminder) that blocks the next steps until it is complete. Show per-lead run state Running, Waiting on person, Completed, Failed, Cancelled, with the failed step surfaced in the pipeline. Keep our versioning (Clio can only cancel and recreate a published workflow).",priority="should"),
dict(feature="Form link lifetime and refresh",our_area="intake",our_screen="intake-questionnaire-send",status="covered",proposal="link_expiry_days and 'Resend fresh link' exist. Add a self-serve refresh window (the client can request a new link up to N days, default 30) to match Clio.",priority="could"),
dict(feature="Appointment reminders up to 5 with firm defaults; video link",our_area="intake",our_screen="consult-types-settings",status="covered",proposal="Already have reminders and video_link. Cap at 5 per booking, add firm-wide defaults, and auto-generate video meeting links through the calendar or video integration.",priority="could"),
dict(feature="SMS: Clio Grow texts are no-reply, fixed templates; two-way only in Manage",our_area="intake",our_screen="lead-detail",status="deliberately different",proposal="Keep firm-written templates under G-form. Make SMS two-way from day one: inbound replies attach to the lead timeline, and STOP/ARRET opt-out is honoured across all channels (already in spec).",priority="should"),
dict(feature="Website builder / Google LSA / Google Analytics events",our_area="intake",our_screen="intake-settings",status="deliberately different",proposal="No website builder or LSA (LSA is US-only). Add an optional analytics hook on the public form and chat that emits form_started, lead_created and chat_started events to the firm's own analytics ID, off by default, with no PII in events.",priority="could"),
dict(feature="Conflict search subject type Keyword, full-name match toggle, per-search label",our_area="conflicts",our_screen="conflict-check-new",status="partial",proposal="Add parties[].kind value 'keyword' (free-text search of matter descriptions, notes and documents, e.g. a property address or vessel name), parties[].require_full_name_match bool (default true for persons), and parties[].label (display only, not searched).",priority="should"),
dict(feature="Share live results link with a colleague",our_area="conflicts",our_screen="conflict-results",status="partial",proposal="We have 'Ask the responsible lawyer on the other matter'. Add 'Share check' that sends an in-app link to any user permitted to see the check (walled users excluded) and logs it.",priority="could"),
dict(feature="Overall status override requires acknowledgement",our_area="conflicts",our_screen="conflict-clearance",status="covered",proposal="The clearance sign-off already needs a rationale. Additionally, when the outcome differs from what the hit dispositions imply, require an explicit acknowledgement and record it on the Clearance.",priority="could"),
dict(feature="KYC/KYB log fields incl. AML and source-of-funds check dates and risk rating at open and close",our_area="conflicts",our_screen="client-identification",status="partial",proposal="Add risk_rating (low|medium|high) + risk_reason at matter opening and again at matter closing. Add aml_check_date and source_of_funds_check_date to IdentityRecord. Show a KYC summary card on the matter. Our verification workflow goes further than Clio's log-only fields.",priority="should"),
dict(feature="Search both intake (prospects) and practice records in one check",our_area="conflicts",our_screen="conflict-search-settings",status="covered",proposal="One app, so declined and sealed prospects are already searched. No change.",priority="could"),
]
corrections=[
dict(our_claim="conflicts.json clio_gaps: 'Clearance memo, consents, walls, laterals, client ID - not in Clio as structured screens'",truth="Partly wrong for client ID. Clio Manage has a structured KYC/KYB field set (settings toggle, region-gated) that records conflict, ID, AML and source-of-funds check dates and a risk rating with reason, on contacts and matters. It is a log, not a verification workflow. Clio's conflict close step also records an overall conflict status with comments, which is a light clearance record. The rest (memo, consents, walls, laterals) is still not structured in Clio, per the sources reviewed.",sources=[KYC,CC]),
dict(our_claim="intake.json clio_gaps: 'Grow AI voice agent and website chat with lead score' (implies the Clio AI set is chat + voice)",truth="Grow AI also has an email agent (connected inbox, auto-replies, 'For review' routing) and automated follow-ups. The voice agent is US only, so Ontario firms on Clio do not get it. AI disclosure is a firm toggle on every channel, as the spec says.",sources=[GAI,EMAILAG,VOICE]),
dict(our_claim="intake.json clio_gaps: 'Scheduler appointment types... where_in_clio: Manage > Settings > Calendar & appointments'",truth="All Scheduler settings live in Clio Grow under Settings > Appointments > Clio Scheduler appointments, not in Manage.",sources=[SCHED]),
dict(our_claim="intake.json clio_gaps: 'Automated workflows (rapid, screening, comprehensive)' at 'Grow > Settings > Automated workflows'",truth="Correct. Also: only draft workflows can be edited (a published one must be cancelled and recreated), only admins build them, and an 'assign task' step blocks later steps.",sources=[WF]),
dict(our_claim="intake.json clio_gaps: 'Lead inbox with ignored view' at 'Grow > Inbox (For review / Ignored)'",truth="The current UI is Leads > Marketing with Untriaged / Ignored subtabs, plus a separate Leads > Appointments list. 'For review' is the label for leads that Grow AI routes to humans, not an inbox tab.",sources=[LEADS,EMAILAG]),
dict(our_claim="versus-clio: 'What Clio has that we don't' omits intake marketing",truth="Clio Grow also ships email marketing campaigns, review-request reputation management, a website builder and Google LSA lead buying. Add these to 'their edge', or mark them as deliberately out of scope.",sources=[MKT,REPU,WEB,LSA]),
dict(our_claim="versus-clio: 'Software ~US$90-150+/user/mo with AI (check)'",truth="Unproven for intake. Grow AI is billed per hired matter that AI assisted (outcome-based, with a free trial and hiring target), on top of the Grow licence. Per-user tier pricing for Grow is not published consistently: third-party sources disagree. Keep '(check)' and note the outcome-based AI fee.",sources=[SUB,GAI]),
]
